for h in $(find src/amr_dispatcher_core/include/amr_dispatcher_core -name '*.hpp' | sort); do rel=${h#src/amr_dispatcher_core/include/}; base=$(basename "$h" .hpp); mod=$(dirname "$rel"); srcmod=$(echo "$mod" | sed 's|amr_dispatcher_core/||'); # exclude its own impl cpp
  all=$(grep -rln -F "#include \"$rel\"" src/amr_dispatcher_ros src/amr_dispatcher_bt/src src/amr_dispatcher_bt/include src/amr_dispatcher_tools src/amr_dispatcher_core/src tools launch scripts 2>/dev/null);
  filtered=$(echo "$all" | grep -v "src/amr_dispatcher_core/src/$srcmod/$base.cpp" | grep -v "^$" | tr '\n' ' ');
  tests=$(grep -rln -F "#include \"$rel\"" test 2>/dev/null | tr '\n' ' ');
  if [ -z "$filtered" ]; then echo "ORPHAN-HDR: $rel | SELF-IMPL: $(echo $all | tr '\n' ' ') | TEST: ${tests:-NONE}"; fi; done; echo "=== cross includes within headers ==="; grep -rn '#include "amr_dispatcher_core/' src/amr_dispatcher_core/include | grep -oE 'amr_dispatcher_core/[a-z_/]+\.hpp' | sort -u | head -40

for h in $(find src/amr_dispatcher_core/include/amr_dispatcher_core -name '*.hpp' | sort); do rel=${h#src/amr_dispatcher_core/include/}; base=$(basename "$h" .hpp); srcmod=$(dirname "$rel" | sed 's|amr_dispatcher_core/||');
  all=$(grep -rln -F "#include \"$rel\"" src/amr_dispatcher_ros src/amr_dispatcher_bt src/amr_dispatcher_tools src/amr_dispatcher_core tools launch scripts test 2>/dev/null | sort);
  filtered=$(echo "$all" | grep -v "src/amr_dispatcher_core/src/$srcmod/$base.cpp");
  # classify
  prod=$(echo "$filtered" | grep -E 'amr_dispatcher_ros|amr_dispatcher_bt/src|amr_dispatcher_bt/include|amr_dispatcher_tools|amr_dispatcher_core/src|tools/|launch/|scripts/' | grep -v "test/" | tr '\n' ' ');
  corehdr=$(echo "$filtered" | grep 'amr_dispatcher_core/include' | grep -v "/$rel" | tr '\n' ' ');
  tst=$(echo "$filtered" | grep -E 'test' | tr '\n' ' ');
  if [ -z "$prod" ]; then echo "### $rel"; echo "   core-hdr-includers: ${corehdr:-NONE}"; echo "   test-includers: ${tst:-NONE}"; fi; done

