21	// 单次加载入口：读 YAML 文件 + 应用 schema 校验。线程安全。
22	class ConfigLoader {
23	 public:
24	  using Validator = std::function<void(const YAML::Node&)>;
25	
26	  ConfigLoader();
27	
28	  // 注册字段 schema：key 形如 "chassis.serial_device"，type 提示，required 表示必须存在。
29	  struct FieldSchema {
30	    std::string key;
31	    std::string type;     // "string" | "int" | "double" | "bool" | "list" | "map"
32	    bool required = false;
33	    std::string default_value;  // YAML 字面量；非空且 required=false 时缺失则补默认
34	  };
35	
36	  void RegisterField(FieldSchema schema);
37	
38	  // 从文件加载；通过 schema 校验；返回根节点供调用方取值。
39	  // 校验失败抛 ConfigError；file 不存在抛 ConfigError。
40	  YAML::Node LoadFromFile(const std::string& path);
41	
42	  // 从字符串加载（同上）
43	  YAML::Node LoadFromString(const std::string& yaml);
44	
45	  // 工具：取节点路径上的标量值
46	  static std::string GetString(const YAML::Node& root, const std::string& key,
47	                               const std::string& fallback = "");
48	  static int GetInt(const YAML::Node& root, const std::string& key, int fallback = 0);
49	  static double GetDouble(const YAML::Node& root, const std::string& key,
50	                          double fallback = 0.0);
51	  static bool GetBool(const YAML::Node& root, const std::string& key, bool fallback = false);
52	
